def even_numbers():
    number = 0
    while True:          # бесконечный цикл — и это нормально
        yield number
        number += 2


for value in even_numbers():
    if value > 10:
        break            # выходим сами, когда достаточно
    print(value)

# 0 2 4 6 8 10

def long_lines(path, limit):
    with open(path, encoding='utf-8') as file:
        for line in file:
            if len(line) > limit:
                yield line.strip()


# Файл может быть на гигабайт — в память попадает одна строка за раз
for line in long_lines('log.txt', 100):
    print(line)

