def sum_list(numbers):
    if not numbers:
        return 0
    return numbers[0] + sum_list(numbers[1:])

def count_items(data):
    total = 0
    for item in data:
        if isinstance(item, list):
            total += count_items(item)
        else:
            total += 1
    return total

